<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { drawPage, EditStaffType, layoutScore, loadScore, NOTEHEAD_SCHEMES, StaffGroup, systemRect, TablatureMinimStyle, TablatureSymbolRepeat, type EditStaffTypeValues, type MasterScore, type TabNoteValues } from '../../src/index'
import { qtrc, useLanguage } from '../i18n'
useLanguage()
const props=defineProps<{model:object}>()
const model=props.model as EditStaffType
const emit=defineEmits<{(e:'close',accepted:boolean):void}>()
const revision=ref(0), template=ref(-1), canvas=ref<HTMLCanvasElement|null>(null)
const previews=import.meta.glob<string>('../../MuseScore/src/notationscene/widgets/resources/*_sample.mscx',{query:'?raw',import:'default'})
let previewFrame=0
const previewScores=new Map<string,Promise<MasterScore>>()
function previewScore(kind:'std'|'tab'){let score=previewScores.get(kind);if(!score){const load=previews[`../../MuseScore/src/notationscene/widgets/resources/${kind}_sample.mscx`];score=load().then(text=>{const s=loadScore(new TextEncoder().encode(text));layoutScore(s);return s});previewScores.set(kind,score)}return score}
const values=computed(()=>{void revision.value;return model.values()})
const enabled=computed(()=>model.enabled())
const textStyles=computed(()=>model.textStyleNames())
const previewKind=computed(()=>values.value.group===StaffGroup.TAB?'tab':'std')
async function renderPreview(){const kind=previewKind.value;const score=await previewScore(kind);const c=canvas.value;if(!c)return;model.updatePreview(score);const r=systemRect(score);if(!r)return;const margin=.1,dpr=window.devicePixelRatio||1,dpi=(c.clientWidth||400)/(r.width+2*margin);c.width=Math.round((c.clientWidth||400)*dpr);c.height=Math.round((r.height+2*margin)*dpi*dpr);c.style.height=`${(r.height+2*margin)*dpi}px`;const ctx=c.getContext('2d');if(!ctx)return;ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);drawPage(score,0,ctx,{dpi:dpi*dpr,background:false,region:{x:(r.x-margin)*dpi*dpr,y:(r.y-margin)*dpi*dpr,width:c.width,height:c.height}})}
watch([revision,previewKind],()=>{cancelAnimationFrame(previewFrame);previewFrame=requestAnimationFrame(()=>void renderPreview())})
const dialog=ref<HTMLDialogElement|null>(null), accepted=ref(false)
onMounted(()=>{dialog.value?.showModal();if(values.value.group!==StaffGroup.PERCUSSION)void renderPreview()})
const tr=(s:string)=>qtrc('EditStaffType',s)
function set(p:Partial<EditStaffTypeValues>){model.set(p);revision.value++}
function number(label:string,key:keyof EditStaffTypeValues,min:number,max:number,step:number,suffix=''){return {label,key,min,max,step,suffix}}
const common=[number('Lines:','lines',1,14,1),number('Line distance:','lineDistance',0,99,.25,'sp')]
const tabNumbers=[number('Size:','fretFontSize',1,99,.5,'pt'),number('Vertical offset:','fretY',-99,99,.1,'sp'),number('Size:','durFontSize',1,99,.5,'pt'),number('Vertical offset:','durY',-99,99,.1,'sp')]
function check(label:string,key:keyof EditStaffTypeValues){return {label,key}}
const checks=[check('Show clef','genClef'),check('Show time signature','genTimesig'),check('Show barlines','showBarlines')]
function accept(){emit('close',true)}
</script>
<template>
 <dialog ref="dialog" class="edit-staff-type" aria-labelledby="edit-staff-type-title" @close.self="emit('close',accepted)">
  <h2 id="edit-staff-type-title">{{tr('Edit staff type')}}</h2><div class="staff-type-body"><div class="staff-type-header"><strong class="group-name">{{tr(values.group===StaffGroup.TAB?'TABLATURE STAFF':values.group===StaffGroup.PERCUSSION?'PERCUSSION STAFF':'STANDARD STAFF')}}</strong><input type="text" readonly :value="values.name" :aria-label="values.name" /></div>
   <div class="staff-type-common"><label v-for="n in common" :key="n.key" class="field-row"><span>{{tr(n.label)}}</span><span class="spin"><input type="number" :min="n.min" :max="n.max" :step="n.step" :value="values[n.key] as number" @input="set({[n.key]:Math.max(n.min,Math.min(n.max,Number(($event.target as HTMLInputElement).value)))})"/><span v-if="n.suffix" class="suffix">{{tr(n.suffix)}}</span></span></label><label v-for="c in checks" :key="c.key" class="check"><input type="checkbox" :checked="values[c.key] as boolean" @change="set({[c.key]:($event.target as HTMLInputElement).checked})"/>{{tr(c.label)}}</label></div>
   <div v-if="values.group===StaffGroup.STANDARD" class="staff-type-page"><label v-for="[label,key] in [['Show key signature','genKeysigPitched'],['Show ledger lines','showLedgerLinesPitched'],['Stemless','stemlessPitched']] as const" :key="key" class="check"><input type="checkbox" :checked="values[key]" @change="set({[key]:($event.target as HTMLInputElement).checked})"/>{{tr(label)}}</label><label class="field-row"><span>{{tr('Notehead scheme:')}}</span><select :value="values.noteHeadScheme" @change="set({noteHeadScheme:Number(($event.target as HTMLSelectElement).value)})"><option v-for="scheme in NOTEHEAD_SCHEMES" :key="scheme" :value="scheme">{{EditStaffType.noteHeadSchemeName(scheme)}}</option></select></label></div>
   <div v-else-if="values.group===StaffGroup.PERCUSSION" class="staff-type-page"><label v-for="[label,key] in [['Show key signature','genKeysigPercussion'],['Stemless','stemlessPercussion'],['Show ledger lines','showLedgerLinesPercussion']] as const" :key="key" class="check"><input type="checkbox" :checked="values[key]" @change="set({[key]:($event.target as HTMLInputElement).checked})"/>{{tr(label)}}</label></div>
   <div v-else class="staff-type-page tab">
    <label class="check"><input type="checkbox" :checked="values.upsideDown" @change="set({upsideDown:($event.target as HTMLInputElement).checked})"/>{{tr('Upside down')}}</label>
    <fieldset class="groupbox"><legend>{{tr('Fret marks')}}</legend><div class="radio-row"><label v-for="[label,v] in [['Text style',true],['Tab font preset',false]] as const" :key="label" class="check"><input type="radio" name="fret-marks" :checked="values.fretUseTextStyle===v" @change="set({fretUseTextStyle:v})"/>{{tr(label)}}</label></div>
     <label v-if="values.fretUseTextStyle" class="field-row"><select :value="values.fretTextStyle" :aria-label="tr('Text style')" @change="set({fretTextStyle:Number(($event.target as HTMLSelectElement).value)})"><option v-for="t in textStyles" :key="t.style" :value="t.style">{{t.name}}</option></select></label>
     <template v-else><label class="field-row"><span>{{tr('Font:')}}</span><select :value="values.fretFontIdx" @change="set({fretFontIdx:Number(($event.target as HTMLSelectElement).value)})"><option v-for="(name,i) in EditStaffType.fretFontNames()" :key="i" :value="i">{{name}}</option></select></label><label v-for="n in tabNumbers.slice(0,2)" :key="n.key" class="field-row"><span>{{tr(n.label)}}</span><span class="spin"><input type="number" :min="n.min" :max="n.max" :step="n.step" :value="values[n.key] as number" @input="set({[n.key]:Math.max(n.min,Math.min(n.max,Number(($event.target as HTMLInputElement).value)))})"/><span class="suffix">{{tr(n.suffix)}}</span></span></label></template>
     <div class="radio-grid"><template v-for="[title,key,yes,no] in [['Marks are drawn:','onLines','On lines','Above lines'],['Lines are:','linesThrough','Continuous','Broken'],['Marks are:','useNumbers','Numbers','Letters']] as const" :key="key"><span>{{tr(title)}}</span><label v-for="[label,v] in [[yes,true],[no,false]] as const" :key="label" class="check"><input type="radio" :name="key" :checked="values[key]===v" @change="set({[key]:v})"/>{{tr(label)}}</label></template></div><label class="check"><input type="checkbox" :checked="values.showTabFingering" @change="set({showTabFingering:($event.target as HTMLInputElement).checked})"/>{{tr('Show fingering in tablature')}}</label>
    </fieldset>
    <fieldset class="groupbox"><legend>{{tr('Note values')}}</legend><label class="field-row"><span>{{tr('Font:')}}</span><select :value="values.durFontIdx" @change="set({durFontIdx:Number(($event.target as HTMLSelectElement).value)})"><option v-for="(name,i) in EditStaffType.durationFontNames()" :key="i" :value="i">{{name}}</option></select></label><label v-for="n in tabNumbers.slice(2)" :key="n.key" class="field-row"><span>{{tr(n.label)}}</span><span class="spin"><input type="number" :min="n.min" :max="n.max" :step="n.step" :value="values[n.key] as number" @input="set({[n.key]:Math.max(n.min,Math.min(n.max,Number(($event.target as HTMLInputElement).value)))})"/><span class="suffix">{{tr(n.suffix)}}</span></span></label>
     <div class="radio-grid"><span>{{tr('Shown as:')}}</span><label v-for="[label,v] in [['None','none'],['Note symbols','symbols'],['Stems and beams','stems']] as const" :key="v" class="check"><input type="radio" name="note-values" :checked="values.noteValues===v" @change="set({noteValues:v as TabNoteValues})"/>{{label==='None'?qtrc('EditStaffType',label,'neither note symbols nor stems and beams'):tr(label)}}</label>
      <span>{{tr('Repeat:')}}</span><label v-for="[label,v] in [['Never',TablatureSymbolRepeat.NEVER],['At new system',TablatureSymbolRepeat.SYSTEM],['At new meas.',TablatureSymbolRepeat.MEASURE],['Always',TablatureSymbolRepeat.ALWAYS]] as const" :key="v" class="check"><input type="radio" name="repeat" :checked="values.symRepeat===v" :disabled="!enabled.valuesRepeat" @change="set({symRepeat:v})"/>{{tr(label)}}</label>
      <span>{{tr('Stem style:')}}</span><label v-for="[label,v,disabled] in [['Beside staff',false,!enabled.stemBeside],['Through staff',true,!enabled.stemThrough]] as const" :key="label" class="check"><input type="radio" name="stem-style" :checked="values.stemThrough===v" :disabled="disabled" @change="set({stemThrough:v})"/>{{tr(label)}}</label>
      <span>{{tr('Stem position:')}}</span><label v-for="[label,v] in [['Above',false],['Below',true]] as const" :key="label" class="check"><input type="radio" name="stem-pos" :checked="values.stemsDown===v" :disabled="!enabled.stemAboveBelow" @change="set({stemsDown:v})"/>{{tr(label)}}</label>
      <span>{{tr('Half notes:')}}</span><label v-for="[label,v,disabled] in [['None',TablatureMinimStyle.NONE,!enabled.minimNone],['As short stem',TablatureMinimStyle.SHORTER,!enabled.minimShort],['As slashed stem',TablatureMinimStyle.SLASHED,!enabled.minimSlashed]] as const" :key="v" class="check"><input type="radio" name="minim" :checked="values.minimStyle===v" :disabled="disabled" @change="set({minimStyle:v})"/>{{label==='None'?qtrc('EditStaffType',label,'neither short nor slashed stem'):tr(label)}}</label></div><label class="check"><input type="checkbox" :checked="values.showRests" @change="set({showRests:($event.target as HTMLInputElement).checked})"/>{{tr('Show rests')}}</label>
    </fieldset>
   </div>
   <fieldset v-if="values.group!==StaffGroup.PERCUSSION" class="groupbox preview"><legend>{{tr('Preview')}}</legend><canvas ref="canvas" class="staff-type-preview" /></fieldset>
   <div class="staff-type-template"><label class="field-row"><span>{{tr('Template:')}}</span><select v-model.number="template"><option :value="-1" hidden/><option v-for="t in model.templates()" :key="t.idx" :value="t.idx">{{t.name}}</option></select></label><button type="button" class="secondary" :disabled="template<0" @click="model.resetToTemplate(template);revision++">{{tr('< Reset to template')}}</button></div>
  </div><div class="dialog-buttons"><button type="button" class="secondary" @click="dialog?.close()">{{qtrc('global','Cancel')}}</button><button type="button" class="primary" @click="accepted=true;dialog?.close()">{{qtrc('global','OK')}}</button></div>
 </dialog>
</template>
